import React from "react";
import "./AppInfo.css";
// import qr from "../../img/qr.svg";
import bgItem from "../../img/bgItem.svg";
import { MdPhoneIphone } from "react-icons/md";
import { MdAndroid } from "react-icons/md";
import { FaApple } from "react-icons/fa";
import qr from "../../img/qr-code.png";

function AppInfo() {
  return (
    <div className="parent">
      <img src={bgItem} className="bg1" alt="" />
      <img src={bgItem} className="bg2" alt="" />
      <div className="container">
        <div className="content">
          <article>
            <div className="phone">
              <MdPhoneIphone />
            </div>
            <h2 className="heading">Мобильное приложение SKY FRU</h2>
            <p className="text">
              Выбирайте места, оплачивайте билеты и получайте их прямо на
              телефон — быстро, просто и без очередей
            </p>
            <div className="download">
              <a href="https://play.google.com/store/apps/details?id=com.navisdevs.skyfru">
                <p>
                  <MdAndroid size={28} />
                </p>
                android
              </a>
              <a href="https://apps.apple.com/kg/app/skyfru/id6747702808 ">
                <p>
                  <FaApple size={28} />
                </p>
                ios
              </a>
            </div>
          </article>
          <div className="qr">
            <img src={qr} alt="QR" />
          </div>
        </div>
      </div>
    </div>
  );
}

export default AppInfo;
