import React, { useEffect, useState } from "react";

function MobileApp() {
  const [message, setMessage] = useState("Определяем ваше устройство...");

  useEffect(() => {
    const userAgent = navigator.userAgent || navigator.vendor || window.opera;

    const appStoreUrl = "https://apps.apple.com/kg/app/skyfru/id6747702808";
    const playStoreUrl = "https://play.google.com/store/apps/details?id=com.navisdevs.skyfru";

    if (/android/i.test(userAgent)) {
      window.location.href = playStoreUrl;
    } else if (/iPad|iPhone|iPod/.test(userAgent) && !window.MSStream) {
      window.location.href = appStoreUrl;
    } else {
      setMessage("Ваше устройство не поддерживается. Откройте ссылку с телефона.");
    }
  }, []);

  return (
    <div
      style={{
        height: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "sans-serif",
        textAlign: "center",
        padding: "20px",
      }}
    >
      <p>{message}</p>
    </div>
  );
}

export default MobileApp;
