import cookies_accept_ru from '../../files/pdf/cookies_accept_ru.pdf'
import cookies_accept_kg from '../../files/pdf/cookies_accept_kg.pdf'
import cookies_accept_en from '../../files/pdf/cookies_accept_en.pdf'

import pers_data_accept_kg from '../../files/pdf/pers_data_accept_kg.pdf'
