import privacy_policy_accept_kg from '../../files/pdf/privacy_policy_accept_kg.pdf'
import privacy_policy_accept_ru from '../../files/pdf/privacy_policy_accept_ru.pdf'
import privacy_policy_accept_en from '../../files/pdf/privacy_policy_accept_en.pdf'

const files = {
  en: {
    consent: pers_data_accept_en,
    cookie: cookies_accept_en,
    privacy: privacy_policy_accept_en,
  },
  ru: {
    consent: pers_data_accept_ru,
    cookie: cookies_accept_ru,
    privacy: privacy_policy_accept_ru,
  },
  kg: {
    consent: pers_data_accept_kg,
    cookie: cookies_accept_kg,
    privacy: privacy_policy_accept_kg,
  }
};

const About = () => {
  const { t, i18n } = useTranslation();

  const currentLanguage = i18n.language?.split("-")[0] || "en";

  const currentFiles = files[currentLanguage] || files["en"];

  return (
    <div className="privacy-policy min-height-60vh">
      <div className="container">
        <div className="deep-links">
          <a href={currentFiles.consent} target="_blank" rel="noreferrer">
            {t("consent")}
          </a>
          <a href={currentFiles.cookie} target="_blank" rel="noreferrer">
            {t("cookie")}
          </a>
          <a href={currentFiles.privacy} target="_blank" rel="noreferrer">
            {t("privacy")}
          </a>
        </div>
      </div>
    </div>
  );
};

export default About;